"""공식 저장소에서 확인한 서지와 조사자 해석을 분리하여 기록한다. 모델 실행 없음."""
import csv, json
from pathlib import Path
ROOT=Path(__file__).parent
fields='paper_id title authors year venue doi_or_arxiv official_url version source_verified full_text_access discussion_access domain axis_tags original_rq dataset stimulus brain_measurement model_method training_objective main_findings scientific_contribution limitations future_directions future_direction_source_location transfer_idea relevant_datasets novelty_risk evidence_level agent verification_date'.split()
# 미션의 실제 필수 목록은 30개다. 확인 범위와 위치 2개를 추가하여 32열로 제공한다.
fields += ['evidence_scope','source_location']
base=dict(version='논문 버전 미확인; 공식 저장소 2026-11-12 스냅샷',source_verified='E2: 공식 저자 저장소의 서지 확인; E1: 아래 지정 코드/README 확인',full_text_access='아니오; 공식 코드/README만 직접 확인',discussion_access='아니오',domain='Vision Decoding / 정서 관련 신경표상으로 방법 전이',brain_measurement='fMRI',future_directions='저자의 Discussion/Future Work 미확인(E0); 조사자 제안은 transfer_idea에 E3로 분리',future_direction_source_location='논문 Discussion 미접근',relevant_datasets='Horikawa 우선; Emo-FilM/Spacetop은 시공간·라벨 정합 확인 후; NSD는 시각 디코더 대조군',novelty_risk='정서 분류 성능 개선만으로 신규성 없음; 가까운 정서 전이 선행연구의 체계적 역검색 미완료',evidence_level='E2',agent='03_vision_decoding',verification_date='2026-11-12',evidence_scope='서지·공식요약=E2; 코드/README 문서 사실=E1; 실험 수치 독립재현 없음; 전이 가설=E3')
rows=[]
def add(**kw):
 d=base|kw
 assert set(d)==set(fields),(set(fields)-set(d),set(d)-set(fields))
 rows.append(d)
add(paper_id='VD01',title='MindEye2: Shared-Subject Models Enable fMRI-To-Image With 1 Hour of Data',authors='Scotti; Tripathy; Torrico; Kneeland; Chen; Narang; Santhirasegaran; Xu; Naselaris; Norman; Abraham',year='2024',venue='ICML 2024 (공식 README 표기)',doi_or_arxiv='arXiv:2403.11207',official_url='https://github.com/MedARC-AI/MindEyeV2',axis_tags='G;J;O;Q;S;X',original_rq='다른 피험자의 사전학습으로 새 피험자의 적은 fMRI에서 영상을 복원·검색할 수 있는가?',dataset='NSD; 사전학습 7명과 보류 피험자 미세조정 구성',stimulus='자연 장면 정지영상',model_method='피험자별 선형 입력층 + 공유 MLP + OpenCLIP ViT-bigG-14 잠재표상 + diffusion prior + SDXL unCLIP',training_objective='BiMixCo에서 SoftCLIP으로 전환; diffusion prior MSE; 선택적 저수준 복원 손실 (훈련 코드 직접 확인)',main_findings='공식 README는 1시간 fine-tuning 복원을 보고. 검색 정정: 뇌→영상 1시간57.4%/40시간98.3%; 영상→뇌 79.0%/98.8%. 독립재현 없음.',scientific_contribution='공유-피험자 디코딩과 적은 데이터 적응을 구분 가능한 모듈로 제공한다는 방법론적 기여',limitations='성능은 NSD 내부; 정서 보존 검증 없음; 수정 전 검색 방향 혼동; 생성 prior와 신경정보 분리 필요',transfer_idea='E3: 공유 정렬 전후 정서 주석 관련 잔여 신경정보의 보존/소실을 외부 자극 블록에서 평가',source_location='sources/mindeye2_readme.txt: Retrieval metric correction, Usage, FAQ, Citation; mindeye2_train_cells.txt cell14/19/20 및 loss; mindeye2_eval_cells.txt cell11')
add(paper_id='VD02',title="Reconstructing the Mind's Eye: fMRI-to-Image with Contrastive Learning and Diffusion Priors",authors='Scotti; Banerjee; Goode; Shabalin; Nguyen; Cohen; Dempster; Verlinde; Yundler; Weisberg; Norman; Abraham',year='2023',venue='NeurIPS 36 (MindEye2 공식 README 인용)',doi_or_arxiv='arXiv:2305.18274',official_url='https://github.com/MedARC-AI/fMRI-reconstruction-NSD',axis_tags='G;J;L;T;X',original_rq='대조학습과 diffusion prior로 fMRI에서 검색에 적합한 특징과 생성에 적합한 특징을 함께 추정할 수 있는가?',dataset='NSD',stimulus='자연 장면 정지영상',model_method='CLIP ViT-L/14 257x768 또는 1x768 예측; diffusion prior; VAE 저수준 경로',training_objective='BiMixCo/SoftCLIP 대조학습과 diffusion prior; 공식 README 옵션 확인',main_findings='README는 test-set/LAION-5B 검색, 고수준 복원과 저수준 VAE 경로를 제공; 성능 수치는 본문 미검증',scientific_contribution='잠재표상 검색과 생성 경로를 별도로 측정할 방법을 제공',limitations='정서 목적함수 없음; CLIP의 의미적 편향과 생성 prior 영향; 외부 검색 후보 분포에 의존',transfer_idea='E3: CLIP 잠재표상·prior 출력·최종 영상별 정서 관련 정보의 변화량을 비교해 생성 prior가 보충한 정보를 분리',source_location='sources/mindeye_readme.txt: General information, Pre-trained Subject1 models, Training; mindeye2_readme.txt: Citation')
add(paper_id='VD03',title='Brain-IT: Image Reconstruction from fMRI via Brain-Interaction Transformer',authors='Roman Beliy; Amit Zalcher; Jonathan Kogman; Navve Wasserman; Michal Irani',year='2026',venue='ICLR 2026 채택 (공식 README 주장; 학회 원문 미확인)',doi_or_arxiv='arXiv:2510.25976',official_url='https://github.com/WeizmannVision/brainit-fmri',version='2025 preprint 식별자; 2026 채택 README; 저장소 SHA a7663eb5002e9ea5f899815326ff52d45be9a2f3',axis_tags='G;H;J;O;X;T',original_rq='여러 뇌의 voxel 및 상호작용 표현을 통해 fMRI→영상 복원과 새 피험자 전이를 구성할 수 있는가?',dataset='NSD 8명; COCO unlabeled 영상에서 합성 fMRI 생성',stimulus='자연 장면 정지영상',model_method='Brain-Interaction Transformer; voxel cluster mapping; VGG/CLIP 유도 decoder; diffusion 및 SDXL enhancement',training_objective='공식 명령: VGG contrastive, CLIP-guided stage1, diffusion stage2; EXT로 합성 데이터 사용',main_findings='공식 구현에 저수준/의미/강화 복원, NSD 내부 held-out 피험자 전이 경로 제공; 성능 수치 미확인',scientific_contribution='피험자 간 voxel 정렬과 영상 복원 상호작용을 조사할 구현을 제공; 생물학적 메커니즘 증명으로 해석하지 않음',limitations='합성 fMRI는 encoder의 누락 정보를 만들 수 없음; 전이는 NSD 내부 확인; 큰 GPU 메모리 요구; 코드 자체 라이선스 명확하지 않음',transfer_idea='E3: 실제 뇌·encoder 예측 뇌·시간/자극 혼합 뇌의 정서 잔차 복원을 대조하여 시각 encoder로 설명되는 정보와 그 밖의 정보를 구분',source_location='sources/brainit_readme.txt 전체; brainit_transfer.txt; brainit_train_decoder.txt:309-342; brainit_decoder_models.txt')
add(paper_id='VD04',title='The Wisdom of a Crowd of Brains: A Universal Brain Encoder',authors='Roman Beliy; Navve Wasserman; Amit Zalcher; Michal Irani',year='2024',venue='arXiv preprint (별도 출판 상태 미확인)',doi_or_arxiv='arXiv:2406.12179',official_url='https://github.com/WeizmannVision/brainit-fmri',axis_tags='H;O;F;J;X',original_rq='여러 피험자의 뇌를 함께 이용하는 공통 영상→fMRI encoder를 구성할 수 있는가?',dataset='NSD; 현재 공유 저장소 구현 기준',stimulus='자연 장면 정지영상',model_method='Universal Brain Encoder; 현재 구현에서 고정 DINOv2 특징과 voxel별 학습 표현',training_objective='현재 encoder 훈련 구현 확인; 세부 loss 구현 및 2024 논문과 현재 코드의 동일성 미확인',main_findings='공식 저장소에서 Brain-IT의 fMRI→영상과 별개의 영상→fMRI 연구로 명시; 현재 구현은 DINOv2를 고정 사용',scientific_contribution='생성 디코더의 시각적 순환 일관성과 실제 뇌 신호를 대조할 영상→뇌 기준 모델',limitations='현재 코드가 원 2024 버전과 완전히 일치하는지 미확인; encoder가 잘 예측하는 신호만 합성됨',transfer_idea='E3: 뇌→영상→예측 뇌 순환 잔차를 정서 정보의 후보로 시험하되 측정오차/시각모델 오차와 경쟁시킴',source_location='sources/brainit_readme.txt: Implementation, Overview; brainit_train_encoder.txt:157-185; brainit_encoder_models.txt')
add(paper_id='VD05',title='High-resolution image reconstruction with latent diffusion models from human brain activity',authors='Yu Takagi; Shinji Nishimoto',year='2023',venue='CVPR 2023 pp.14453–14463 (README BibTeX)',doi_or_arxiv='10.1101/2022.11.18.517004 (README bioRxiv 링크; 정식 DOI 미확인)',official_url='https://github.com/yu-takagi/StableDiffusionReconstruction',axis_tags='G;H;L;B;C;T',original_rq='사전학습 latent diffusion model과 뇌에서 추정한 잠재변수로 고해상도 자극 영상을 재구성할 수 있는가?',dataset='NSD',stimulus='자연 장면 정지영상',model_method='Stable Diffusion1.4; early ROI→init_latent와 ventral ROI→c의 ridge 회귀',training_objective='잠재특징 대상 ridge regression; 생성기의 사전학습 목적과 신경 회귀 목적 분리',main_findings='CVPR 구현의 early/ventral 두 decoding 입력 및 이후 확장 경로 확인; 논문 정확도 미확인',scientific_contribution='저수준/의미 조건을 분리하는 간결한 기준선 제공',limitations='ROI별 입력 분리는 ROI의 기능적 전담/인과 기여를 입증하지 않음; diffusion은 조건에 없는 세부를 생성 가능',transfer_idea='E3: 저수준과 의미 조건을 교차 고정해 정서 관련 잔차를 보존하는 경로를 검증; 생성 변화만으로 신경 인과성을 주장하지 않음',source_location='sources/takagi_readme.txt: Reconstruction based on CVPR method, Citation')
add(paper_id='VD06',title='Improving visual image reconstruction from human brain activity using latent diffusion models via multiple decoded inputs',authors='Yu Takagi; Shinji Nishimoto',year='2023',venue='arXiv technical report',doi_or_arxiv='arXiv:2306.11536',official_url='https://github.com/yu-takagi/StableDiffusionReconstruction',axis_tags='G;L;R;B;C;X',original_rq='뇌에서 별도로 복원한 텍스트·GAN·깊이 입력이 영상 복원에 어떻게 기여하는가?',dataset='NSD',stimulus='자연 장면 정지영상',model_method='BLIP caption; VGG/GAN; DPT depth; Stable Diffusion1.4/2.0의 다중 디코딩 입력',training_objective='각 특징에 대한 ridge regression과 다중 조건 생성; 상세 비교 실험은 미확인',main_findings='README는 여러 추가 기법의 정확도 향상을 보고하며 실행 명령을 제공; 수치·통계는 미확인',scientific_contribution='내용·공간·저수준 조건을 나누어 해석하는 분석 도구',limitations='조건이 서로 독립적이라는 보장은 없음; 각 모델 오차가 정서 효과로 오인될 수 있음',transfer_idea='E3: 정서 정보가 객체 의미가 같은 자극에서도 공간/깊이·장면 구성 경로로 남는지 모듈 삭제로 시험',source_location='sources/takagi_readme.txt: General Information, Decoded Text Prompt/GAN/Depth, Following technical report')
add(paper_id='VD07',title='Brain-Diffuser: Natural scene reconstruction from fMRI signals using generative latent diffusion',authors='Furkan Ozcelik; Rufin VanRullen',year='2023',venue='arXiv 기록 연결; 최종 저널 서지 미확인',doi_or_arxiv='arXiv:2303.05334',official_url='https://github.com/ozcelikfu/brain-diffuser',axis_tags='G;L;B;C;R;T',original_rq='저수준 VDVAE와 CLIP 기반 확산 조건을 결합하여 fMRI 자극을 재구성할 수 있는가?',dataset='NSD subject1/2/5/7',stimulus='자연 장면 정지영상과 COCO captions',model_method='VDVAE latent regression + CLIP-Vision/Text regression + Versatile Diffusion',training_objective='영상·텍스트·VDVAE 특징으로 회귀 후 생성; README의 단계별 코드 경로 확인',main_findings='분리된 VDVAE/CLIP-Text/CLIP-Vision 경로와 재구성 평가 구현 확인. README는 ROI 분석 버그로 원 결과의 정확 재현 불가 명시.',scientific_contribution='여러 복원 경로를 서로 경쟁시키는 분석 구조',limitations='공식 README에 ROI 분석 버그 경고; 생성 변동; 캡션이 정서 정보의 직접 주석을 대신하지 못함',transfer_idea='E3: 시각·텍스트 의미 조건에서 각각 유지되는 정서 신경정보를 교차검증하고 ROI 그림을 증거로 쓰지 않음',source_location='sources/brain_diffuser_readme.txt: First/Second Stage, ROI Analysis')
add(paper_id='VD08',title='Seeing Beyond the Brain: Masked Modeling Conditioned Diffusion Model for Human Vision Decoding',authors='Zijiao Chen; Jiaxin Qing; Tiange Xiang; Wan Lin Yue; Juan Helen Zhou',year='2023',venue='CVPR 2023 (README BibTeX)',doi_or_arxiv='식별자 미확인; 공식 논문 제목/저자/학회 확인',official_url='https://github.com/zjc062/mind-vis',axis_tags='G;J;F;Q;S',original_rq='비대응 뇌 데이터의 masked pretraining으로 적은 영상-뇌 쌍에서 복원할 수 있는가?',dataset='HCP+GOD 약136000 samples/1205 subjects (README); GOD/BOLD5000 decoding',stimulus='resting-state 사전학습 후 시각 자극 영상 대응',model_method='MinD-Vis: Sparse Masked Brain Modeling + Double-Conditioned LDM',training_objective='masked brain modeling 후 fMRI-image pair로 cross-attention와 뇌 encoder 공동학습',main_findings='README는 적은 주석에서 의미에 부합하는 복원을 보고; StageA2가 test-set fMRI만으로 비지도 적응한다고 명시',scientific_contribution='영상 라벨 이전 뇌 사전학습과 시각 조건 학습을 구분하는 전이 분석 기준',limitations='test-set fMRI 적응은 transductive 설정; 정서 잔차 정보 보존 미검증; HCP 사용 라이선스 별도',transfer_idea='E3: masked 재구성 대 contrastive 정렬이 예측력 밖의 정서 관련 신경정보를 보존하는지 동일 자료·split에서 비교',source_location='sources/mindvis_readme.txt: Abstract, Download data, SC-MBM, StageB, Citation')
